async function saveManifest(man){
  try{
    const mb64 = Buffer.from(JSON.stringify(man)).toString('base64');
    await storage.uploadPng('premiere/manifest.json', mb64, 'application/json');
  }catch(e){ console.error('PREMIERE MANIFEST SAVE FAIL', e.message); }
}
exports.handler = async (event) => {
  const q=(event&&event.queryStringParameters)||{};
  const only=(q.only||'').split(',').map(function(x){return x.trim();}).filter(Boolean);
  const redoSlug=(q.redo && q.redo!=='shots' && q.redo!=='music') ? q.redo.trim() : '';
  if(!process.env.ORDER_START_KEY || q.key!==process.env.ORDER_START_KEY)
    return { statusCode:403, body:'forbidden' };
  const RUN=Math.random().toString(36).slice(2,8).toUpperCase();
  console.log('PREMIERE FACTORY BUILD CO99 RUN',RUN);
  console.log('PREMIERE PARAMS only='+JSON.stringify(only)+' redo='+(q.redo||'(none)'));
  console.log('PREMIERE KEYS openai:'+(OA?'present':'MISSING')+' gemini:'+(GK?'present':'MISSING'));
  await storage.ensureBucket();
  const SBP = process.env.SUPABASE_URL+'/storage/v1/object/public/'+storage.BUCKET;
  // CO88 single-run lock: one factory run at a time; stale locks (>20 min) auto-expire
  try{
    const lr = await fetch(SBP+'/premiere/factory-lock.json?cb='+Date.now());
    if(lr.ok){ const lj = await lr.json();
      if(lj && lj.running && (Date.now()-new Date(lj.at).getTime()) < 20*60*1000){
        console.log('PREMIERE BLOCKED: run',lj.run,'already in progress since',lj.at);
        return { statusCode:409, body:JSON.stringify({blocked:true, running:lj.run, since:lj.at}) };
      } }
  }catch(e){}
  await storage.uploadPng('premiere/factory-lock.json',
    Buffer.from(JSON.stringify({running:true,run:RUN,at:new Date().toISOString()})).toString('base64'),'application/json');
  // CO78: seed from the existing manifest so partial runs never blank out finished brands
  const man = { made_at:new Date().toISOString(), brands:{} };
  try{
    const prev = await fetch(SBP+'/premiere/manifest.json?cb='+Date.now());
    if(prev.ok){ const pj = await prev.json(); if(pj && pj.brands) man.brands = pj.brands; }
  }catch(e){}
  // CO78: brands missing scene media render FIRST so heavy new work isn't queued behind reuse passes
  const order=[];
  for(const b of BRANDS){
    let missing=true;
    try{ missing = !(await fetch(SBP+'/premiere/'+b.slug+'-scene1.mp4',{method:'HEAD'})).ok; }catch(e){}
    order.push({b,missing});
  }
  order.sort((a,z)=>(z.missing?1:0)-(a.missing?1:0));
  console.log('PREMIERE ORDER', order.map(o=>o.b.slug+(o.missing?'*':'')).join(','));
  for(const {b} of order){
    man.brands[b.slug]={};
    try{
      const vu = SBP+'/premiere/'+b.slug+'-voice.mp3';
      const vhead = (redoSlug===b.slug || only.indexOf(b.slug+'-voice')>-1) ? {ok:false} : await fetch(vu,{method:'HEAD'});
      if(vhead.ok){ man.brands[b.slug].voice = vu+'?v='+V; console.log('PREMIERE voice REUSED (locked take)',b.slug); }
      else { man.brands[b.slug].voice = await tts(b); console.log('PREMIERE voice OK',b.slug); }
    }catch(e){ console.error('PREMIERE VOICE FAIL',b.slug,e.message); man.brands[b.slug].voice_error=String(e.message).slice(0,200); }
    try{
      const mu = SBP+'/premiere/'+b.slug+'-music.mp3';
      const mhead = (q.redo==='music' || redoSlug===b.slug || only.indexOf(b.slug+'-music')>-1) ? {ok:false} : await fetch(mu,{method:'HEAD'});
      if(mhead.ok){ man.brands[b.slug].music = mu+'?v='+V; console.log('PREMIERE music REUSED',b.slug); }
      else { man.brands[b.slug].music = await lyria(b.slug); console.log('PREMIERE music OK',b.slug); }
    }catch(e){ console.error('PREMIERE MUSIC FAIL',b.slug,e.message); }
    man.brands[b.slug].shots=[];
    const NSC=(STORY[b.slug]||[]).length||3;
    for(let ix=1; ix<=NSC; ix++){
      try{
        const u = SBP+'/premiere/'+b.slug+'-scene'+ix+'.mp4';
        const force = redoSlug===b.slug || only.indexOf(b.slug)>-1 || only.indexOf(b.slug+'-'+ix)>-1 || (!only.length && q.redo==='shots');
        if(force) console.log('PREMIERE FORCE RENDER',b.slug,ix);
        const head = force ? {ok:false} : await fetch(u,{method:'HEAD'});
        if(head.ok){ man.brands[b.slug].shots.push(u+'?v='+V); console.log('PREMIERE scene REUSED',b.slug,ix); }
        else { man.brands[b.slug].shots.push(await veo(STORY[b.slug][ix-1], b.slug, ix)); console.log('PREMIERE scene OK',b.slug,ix); }
      }catch(e){ console.error('PREMIERE SCENE FAIL',b.slug,ix,e.message);
        man.brands[b.slug].shot_errors=(man.brands[b.slug].shot_errors||[]).concat('scene'+ix+': '+String(e.message).slice(0,220)); }
      if(man.brands[b.slug].shots.length) man.brands[b.slug].shot=man.brands[b.slug].shots[0];
      // CO78: checkpoint after every scene — a killed run can no longer lose finished media
      await saveManifest(man);
      console.log('PREMIERE manifest checkpoint',b.slug,ix);
    }
  }
  // prune keys for brands no longer on the wall
  const clean={}; for(const b of BRANDS) if(man.brands[b.slug]) clean[b.slug]=man.brands[b.slug];
  man.brands=clean;
  await saveManifest(man);
  await storage.uploadPng('premiere/factory-lock.json',
    Buffer.from(JSON.stringify({running:false,run:RUN,done_at:new Date().toISOString()})).toString('base64'),'application/json');
  console.log('PREMIERE FACTORY COMPLETE RUN',RUN, JSON.stringify(man));
  return { statusCode:200, body:JSON.stringify(man) };
};
